def clean(df):
    df = df.copy()
    # Clean Region: strip whitespace, normalize case (title), keep only allowed values
    if 'Region' in df.columns:
        df['Region'] = df['Region'].apply(lambda x: x.strip().title() if isinstance(x, str) else x)
        allowed = {'North', 'South', 'East', 'West'}
        # set any non-allowed non-NA to NA (preserves NaN)
        mask = df['Region'].notna() & ~df['Region'].isin(allowed)
        df.loc[mask, 'Region'] = pd.NA
    # Ensure numeric Quantity/Price
    df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce')
    df['Price'] = pd.to_numeric(df['Price'], errors='coerce')
    # Remove invalid Quantity (min 1, positive whole number)
    df = df[df['Quantity'] >= 1]
    df = df.dropna(subset=['Quantity', 'Price'])
    # Clean Date to YYYY-MM-DD
    df['Date'] = pd.to_datetime(df['Date'], errors='coerce')
    # Recompute Revenue = Quantity * Price
    df['Revenue'] = df['Quantity'] * df['Price']
    # Clean Category whitespace
    if 'Category' in df.columns:
        df['Category'] = df['Category'].apply(lambda x: x.strip() if isinstance(x, str) else x)
    return df

def answer(df):
    # total revenue by region for Electronics
    d = df[df['Category'] == 'Electronics'].copy()
    d = d.dropna(subset=['Region'])
    if d.empty:
        return {}
    grouped = d.groupby('Region', dropna=True)['Revenue'].sum()
    # convert to plain dict, int when possible
    out = {}
    for k, v in grouped.items():
        if pd.isna(k):
            continue
        # v is numeric
        if isinstance(v, float) and v.is_integer():
            v = int(v)
        elif isinstance(v, (int, float)):
            # keep int if whole number
            try:
                if float(v).is_integer():
                    v = int(v)
            except:
                pass
        out[str(k)] = v
    return out
